     * Rewrites the address bar to match the filter. It replaces the current
     * history entry rather than pushing one, so typing a name does not bury the
     * page the user came from under a stack of half-typed filters.
     *
     * <p>This is what {@code History.replaceState} does, spelled out, because
     * {@link QueryParameters} percent-escapes the separators in
     * {@code status=ACTIVE,CLOSED} and the URL is nicer to read and to paste
     * with the commas left alone.
     */
    private void writeQueryParameters() {
        String url = urlFor(filter);
        getUI().ifPresent(ui -> {
            if (ui.getSession().getService().getDeploymentConfiguration().isReactEnabled()) {
                ui.getPage().executeJs("window.dispatchEvent(new CustomEvent('vaadin-navigate', "
                        + "{ detail: { state: null, url: $0, replace: true, callback: false } }));", url);
            } else {
                ui.getPage().executeJs("window.history.replaceState(null, '', $0); "
                        + "window.dispatchEvent(new CustomEvent('vaadin-navigated'));", url);
            }
        });
    }

    /** This view's URL carrying the given filter, relative to the current page. */
    static String urlFor(CustomerFilter filter) {
        String query = queryStringFor(filter);
        // "." is the current directory: the same page, without a query string.
        return query.isEmpty() ? "." : "?" + query;
    }

    static String queryStringFor(CustomerFilter filter) {
        StringBuilder query = new StringBuilder();
        String name = filter.name().trim();
        if (!name.isEmpty()) {
            query.append(NAME_PARAMETER).append('=').append(encode(name));
        }
        if (!filter.statuses().isEmpty()) {
            if (!query.isEmpty()) {
                query.append('&');
            }
            query.append(STATUS_PARAMETER).append('=').append(encode(formatStatuses(filter.statuses())));
        }
        return query.toString();
    }

