/** What {@link CustomerFilter} considers a match. */
class CustomerFilterTest {

    private static final Customer MAKINEN = new Customer(
            1, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.ACTIVE);
    private static final Customer JOSEPHINE = new Customer(
            2, "Joséphine", "Aaltonen", "jo@example.com", "Portugal", CustomerStatus.CLOSED);
    private static final Customer ADA = new Customer(
            3, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);

    private static boolean matches(String name, Customer customer) {
        return CustomerFilter.byName(name).matches(customer);
    }

    @Test
    void anEmptyFilterMatchesEverything() {
        assertTrue(CustomerFilter.EMPTY.isEmpty());
        assertTrue(CustomerFilter.EMPTY.matches(MAKINEN));
        assertTrue(CustomerFilter.byName("   ").isEmpty());
        assertTrue(CustomerFilter.byName("   ").matches(MAKINEN));
    }

    @Test
    void everyTermHasToMatchOneOfTheNames() {
        assertTrue(matches("ada aal", ADA));
        assertTrue(matches("aal ada", ADA));
        assertTrue(matches("  ada   aal  ", ADA));
        assertFalse(matches("ada virtanen", ADA));
    }

    @Test
    void aTermMayMatchEitherName() {
        assertTrue(matches("jarno", MAKINEN));
        assertTrue(matches("kine", MAKINEN));
        assertFalse(matches("jarno", ADA));
    }

    @Test
    void theEmailAndCountryAreNotNames() {
        assertFalse(matches("example.com", MAKINEN));
        assertFalse(matches("netherlands", MAKINEN));
    }

    @ParameterizedTest
    @ValueSource(strings = { "mäkinen", "makinen", "MAKINEN", "MÄKINEN", "MäKiNeN" })
    void caseAndAccentsAreIgnoredInBothDirections(String typed) {
        assertTrue(matches(typed, MAKINEN), typed + " must match Mäkinen");
    }

    @ParameterizedTest
    @ValueSource(strings = { "josephine", "joséphine", "JOSEPHINE" })
    void anAccentedNameIsFoundWithoutTheAccent(String typed) {
        assertTrue(matches(typed, JOSEPHINE), typed + " must match Joséphine");
    }

    @Test
    void noStatusSelectedMeansEveryStatus() {
        assertTrue(CustomerFilter.byStatus(Set.of()).matches(MAKINEN));
        assertTrue(CustomerFilter.byStatus(Set.of()).matches(JOSEPHINE));
    }

    @Test
    void aSelectedStatusExcludesTheOthers() {
        CustomerFilter active = CustomerFilter.byStatus(Set.of(CustomerStatus.ACTIVE));
        assertTrue(active.matches(MAKINEN));
        assertFalse(active.matches(JOSEPHINE));

        CustomerFilter both = CustomerFilter.byStatus(
                Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
        assertTrue(both.matches(MAKINEN));
        assertTrue(both.matches(JOSEPHINE));
    }

    @Test
    void bothPartsHaveToMatch() {
        CustomerFilter filter = new CustomerFilter("aal", Set.of(CustomerStatus.CLOSED));
        assertTrue(filter.matches(JOSEPHINE));
        assertFalse(filter.matches(ADA), "Ada Aaltonen is ACTIVE, not CLOSED");
        assertFalse(filter.matches(MAKINEN), "Mäkinen does not match the name");
