+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** A filter with the given statuses and no name restriction. */
+    public static CustomerFilter byStatus(Collection<CustomerStatus> statuses) {
+        return new CustomerFilter("", new LinkedHashSet<>(statuses));
+    }
+
+    /** {@code true} when this filter accepts every customer. */
+    public boolean isEmpty() {
+        return terms().isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name filter split into the terms that all have to match. */
+    public List<String> terms() {
+        String trimmed = name.trim();
+        if (trimmed.isEmpty()) {
+            return List.of();
+        }
+        return List.of(WHITESPACE.split(normalize(trimmed)));
+    }
+
+    /**
+     * Compiles this filter into a predicate. The terms are normalised once, not
+     * once per row, so a query costs one pass over the data set.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = terms();
+        if (terms.isEmpty() && statuses.isEmpty()) {
+            return customer -> true;
+        }
+        return customer -> matchesStatus(customer) && matchesName(terms, customer);
+    }
+
+    /** {@code true} when the given customer passes this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private static boolean matchesName(List<String> terms, Customer customer) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds a string down to something comparable: accents decomposed and
+     * dropped, everything lower case.
+     */
+    static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
