+
+        nameField().fill("");
+        waitForSummary("Showing 500 of 500");
+        assertEquals("", queryString(), "An empty filter must leave no parameters behind");
+    }
+
+    @Test
+    void aLinkWithParametersOpensTheFilteredList() {
