diff --git a/src/test/java/com/example/customers/domain/CustomerFilterTest.java b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
new file mode 100644
index 0000000..e9f663c
--- /dev/null
+++ b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
@@ -0,0 +1,109 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.params.ParameterizedTest;
+import org.junit.jupiter.params.provider.ValueSource;
+
+/** What {@link CustomerFilter} considers a match. */
+class CustomerFilterTest {
+
+    private static final Customer MAKINEN = new Customer(
+            1, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            2, "Joséphine", "Aaltonen", "jo@example.com", "Portugal", CustomerStatus.CLOSED);
+    private static final Customer ADA = new Customer(
+            3, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+
+    private static boolean matches(String name, Customer customer) {
+        return CustomerFilter.byName(name).matches(customer);
+    }
+
+    @Test
+    void anEmptyFilterMatchesEverything() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(CustomerFilter.EMPTY.matches(MAKINEN));
+        assertTrue(CustomerFilter.byName("   ").isEmpty());
+        assertTrue(CustomerFilter.byName("   ").matches(MAKINEN));
+    }
+
+    @Test
+    void everyTermHasToMatchOneOfTheNames() {
+        assertTrue(matches("ada aal", ADA));
+        assertTrue(matches("aal ada", ADA));
+        assertTrue(matches("  ada   aal  ", ADA));
+        assertFalse(matches("ada virtanen", ADA));
+    }
+
+    @Test
+    void aTermMayMatchEitherName() {
+        assertTrue(matches("jarno", MAKINEN));
+        assertTrue(matches("kine", MAKINEN));
+        assertFalse(matches("jarno", ADA));
+    }
+
+    @Test
+    void theEmailAndCountryAreNotNames() {
+        assertFalse(matches("example.com", MAKINEN));
+        assertFalse(matches("netherlands", MAKINEN));
+    }
+
+    @ParameterizedTest
+    @ValueSource(strings = { "mäkinen", "makinen", "MAKINEN", "MÄKINEN", "MäKiNeN" })
+    void caseAndAccentsAreIgnoredInBothDirections(String typed) {
+        assertTrue(matches(typed, MAKINEN), typed + " must match Mäkinen");
+    }
+
+    @ParameterizedTest
+    @ValueSource(strings = { "josephine", "joséphine", "JOSEPHINE" })
+    void anAccentedNameIsFoundWithoutTheAccent(String typed) {
+        assertTrue(matches(typed, JOSEPHINE), typed + " must match Joséphine");
+    }
+
+    @Test
+    void noStatusSelectedMeansEveryStatus() {
+        assertTrue(CustomerFilter.byStatus(Set.of()).matches(MAKINEN));
+        assertTrue(CustomerFilter.byStatus(Set.of()).matches(JOSEPHINE));
+    }
+
+    @Test
+    void aSelectedStatusExcludesTheOthers() {
+        CustomerFilter active = CustomerFilter.byStatus(Set.of(CustomerStatus.ACTIVE));
+        assertTrue(active.matches(MAKINEN));
+        assertFalse(active.matches(JOSEPHINE));
+
+        CustomerFilter both = CustomerFilter.byStatus(
+                Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertTrue(both.matches(MAKINEN));
+        assertTrue(both.matches(JOSEPHINE));
+    }
+
+    @Test
+    void bothPartsHaveToMatch() {
+        CustomerFilter filter = new CustomerFilter("aal", Set.of(CustomerStatus.CLOSED));
+        assertTrue(filter.matches(JOSEPHINE));
+        assertFalse(filter.matches(ADA), "Ada Aaltonen is ACTIVE, not CLOSED");
+        assertFalse(filter.matches(MAKINEN), "Mäkinen does not match the name");
+    }
+
+    @Test
+    void theTermsAreNormalisedOnce() {
+        assertEquals(List.of("ada", "aal"), CustomerFilter.byName("  Ada   AAL ").terms());
+        assertEquals(List.of("makinen"), CustomerFilter.byName("Mäkinen").terms());
+        assertEquals(List.of(), CustomerFilter.byName(" ").terms());
+    }
+
+    @Test
+    void filtersWithTheSameContentAreEqual() {
+        assertEquals(
+                new CustomerFilter("vir", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)),
+                new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+        assertEquals(CustomerFilter.EMPTY, new CustomerFilter("", Set.of()));
+    }
+}
diff --git a/src/test/java/com/example/customers/domain/CustomerRepositoryTest.java b/src/test/java/com/example/customers/domain/CustomerRepositoryTest.java
new file mode 100644
index 0000000..8cf5b70
--- /dev/null
+++ b/src/test/java/com/example/customers/domain/CustomerRepositoryTest.java
@@ -0,0 +1,86 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+/** The repository pages, sorts, filters and counts — and records every query. */
+class CustomerRepositoryTest {
+
+    private static final CustomerFilter VIRTANEN = CustomerFilter.byName("virtanen");
+
+    private QueryLog queryLog;
+    private CustomerRepository repository;
+
+    @BeforeEach
+    void setUp() {
+        queryLog = new QueryLog();
+        repository = new CustomerRepository(queryLog);
+        queryLog.clear();
+    }
+
+    @Test
+    void countingRespectsTheFilter() {
+        assertEquals(500, repository.count());
+        assertEquals(15, repository.count(VIRTANEN));
+        assertEquals(167, repository.count(CustomerFilter.byStatus(Set.of(CustomerStatus.ACTIVE))));
+        assertEquals(5, repository.count(
+                new CustomerFilter("virtanen", Set.of(CustomerStatus.ACTIVE))));
+        assertEquals(0, repository.count(CustomerFilter.byName("nobody")));
+    }
+
+    @Test
+    void aPageIsCutOutOfTheMatchesOnly() {
+        List<CustomerSort> byLastName = List.of(new CustomerSort("lastName", true));
+
+        List<Customer> firstFive = repository.findAll(0, 5, byLastName, VIRTANEN);
+        assertEquals(5, firstFive.size());
+        assertTrue(firstFive.stream().allMatch(VIRTANEN::matches));
+
+        List<Customer> allFifteen = repository.findAll(0, 20, byLastName, VIRTANEN);
+        assertEquals(15, allFifteen.size());
+        assertEquals(allFifteen.subList(0, 5), firstFive);
+        assertEquals(allFifteen.subList(10, 15), repository.findAll(10, 5, byLastName, VIRTANEN));
+    }
+
+    @Test
+    void sortingAppliesToTheMatches() {
+        List<Customer> ascending = repository.findAll(
+                0, 20, List.of(new CustomerSort("firstName", true)), VIRTANEN);
+        List<Customer> descending = repository.findAll(
+                0, 20, List.of(new CustomerSort("firstName", false)), VIRTANEN);
+
+        assertEquals("Beatriz", ascending.get(0).firstName());
+        assertEquals("Wilma", descending.get(0).firstName());
+        assertEquals(15, ascending.size());
+    }
+
+    @Test
+    void aFilteredPageIsStillCapped() {
+        assertThrows(IllegalArgumentException.class,
+                () -> repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of(), VIRTANEN));
+    }
+
+    @Test
+    void everyQueryIsRecordedOnce() {
+        repository.findAll(0, 50, List.of(), VIRTANEN);
+        assertEquals(List.of(new QueryLog.PageQuery(0, 50, 15)), queryLog.pageQueries());
+        assertEquals(List.of(), queryLog.countQueries());
+
+        repository.count(VIRTANEN);
+        assertEquals(List.of(15), queryLog.countQueries());
+
+        repository.count();
+        assertEquals(List.of(15, 500), queryLog.countQueries());
+
+        repository.findAll(0, 50, List.of());
+        assertEquals(2, queryLog.pageQueries().size());
+        assertEquals(65, queryLog.rowsFetched());
+    }
+}
