@@ -0,0 +1,72 @@
+package com.example.customers.ui;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** How {@link CustomerListView} spells the filter out in the URL, and reads it back. */
+class CustomerFilterUrlTest {
+
+    @Test
+    void anEmptyFilterLeavesNoParametersBehind() {
+        assertEquals("", CustomerListView.queryStringFor(CustomerFilter.EMPTY));
+        assertEquals(".", CustomerListView.urlFor(CustomerFilter.EMPTY));
+        assertEquals(".", CustomerListView.urlFor(CustomerFilter.byName("   ")));
+    }
+
+    @Test
+    void theNameIsPercentEscaped() {
+        assertEquals("?name=vir", CustomerListView.urlFor(CustomerFilter.byName(" vir ")));
+        assertEquals("?name=m%C3%A4kinen%20a",
+                CustomerListView.urlFor(CustomerFilter.byName("mäkinen a")));
+    }
+
+    @Test
+    void theStatusesAreOneCommaSeparatedValueInDeclarationOrder() {
+        assertEquals("?status=ACTIVE,CLOSED",
+                CustomerListView.urlFor(CustomerFilter.byStatus(
+                        Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE))));
+        assertEquals("?status=ACTIVE,PENDING,CLOSED",
+                CustomerListView.urlFor(CustomerFilter.byStatus(Set.of(CustomerStatus.values()))));
+    }
+
+    @Test
+    void bothParametersAppearTogether() {
+        assertEquals("?name=vir&status=ACTIVE,CLOSED",
+                CustomerListView.urlFor(new CustomerFilter("vir",
+                        Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED))));
+    }
+
+    @Test
+    void theStatusParameterIsReadBack() {
+        assertEquals(Set.of(), CustomerListView.parseStatuses(List.of()));
+        assertEquals(Set.of(CustomerStatus.ACTIVE),
+                CustomerListView.parseStatuses(List.of("ACTIVE")));
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                CustomerListView.parseStatuses(List.of("ACTIVE,CLOSED")));
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                CustomerListView.parseStatuses(List.of("ACTIVE", "CLOSED")),
+                "Repeated parameters read the same as one comma-separated value");
+    }
+
+    @Test
+    void nonsenseInTheStatusParameterIsIgnored() {
+        assertEquals(Set.of(CustomerStatus.ACTIVE),
+                CustomerListView.parseStatuses(List.of("ACTIVE,,DELETED, active ")));
+        assertEquals(Set.of(), CustomerListView.parseStatuses(List.of("")));
+    }
+
+    @Test
+    void whatIsWrittenIsWhatIsRead() {
+        CustomerFilter filter = new CustomerFilter("vir",
+                Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertEquals(filter.statuses(), CustomerListView.parseStatuses(
+                List.of(CustomerListView.formatStatuses(filter.statuses()))));
+    }
+}
